//! Parity of fast-rich's theme style names and named colors with Python
//! Rich 15, using `tests/fixtures/default_styles.golden` (generated by
//! `scripts/gen_default_styles.py`) and `tests/fixtures/color_names.golden`
//! (generated by `scripts/gen_color_names.py`).
//!
//! For every name in Rich's `DEFAULT_STYLES`, the style fast-rich resolves
//! through `Theme::new()` must have Rich's color, background color and
//! bold / dim / italic / underline / blink / reverse / conceal (`hidden`) /
//! strike flags. Rich's `not X` (explicitly off) is compared as "off",
//! since fast-rich's `Style` has no separate "unset" state. Attributes
//! fast-rich's `Style` lacks (`blink2`, `underline2`, `frame`, `encircle`,
//! `overline`) are listed in the golden and skipped.

use fast_rich::style::{Color, Style};
use fast_rich::theme::{builtin_style_names, Theme};

const STYLES_GOLDEN: &str = include_str!("fixtures/default_styles.golden");
const COLORS_GOLDEN: &str = include_str!("fixtures/color_names.golden");

/// Encode a color the way the generator does: `-`, `default`, `n<index>`
/// or `#rrggbb`.
fn encode(color: Option<Color>) -> String {
    let index = |c: Color| match c.to_ansi256() {
        Color::Ansi256(n) => n,
        _ => unreachable!(),
    };
    match color {
        None => "-".into(),
        Some(Color::Default) => "default".into(),
        Some(Color::Rgb { r, g, b }) => format!("#{r:02x}{g:02x}{b:02x}"),
        Some(c) => format!("n{}", index(c)),
    }
}

fn flags(style: &Style) -> [bool; 8] {
    [
        style.bold,
        style.dim,
        style.italic,
        style.underline,
        style.blink,
        style.reverse,
        style.hidden,
        style.strikethrough,
    ]
}

struct Record<'a> {
    name: &'a str,
    color: &'a str,
    bgcolor: &'a str,
    flags: Vec<&'a str>,
    unsupported: &'a str,
}

fn records() -> Vec<Record<'static>> {
    STYLES_GOLDEN
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|line| {
            let f: Vec<&str> = line.split(' ').collect();
            assert_eq!(f.len(), 12, "bad golden line: {line}");
            Record {
                name: f[0],
                color: f[1],
                bgcolor: f[2],
                flags: f[3..11].to_vec(),
                unsupported: f[11],
            }
        })
        .collect()
}

#[test]
fn every_default_style_matches_rich() {
    const ATTRS: [&str; 8] = [
        "bold",
        "dim",
        "italic",
        "underline",
        "blink",
        "reverse",
        "conceal",
        "strike",
    ];
    let theme = Theme::new();
    let records = records();
    assert_eq!(records.len(), 154, "Rich 15 has 154 default styles");

    let mut failures = Vec::new();
    for r in &records {
        let Some(style) = theme.lookup_style(r.name) else {
            failures.push(format!("{}: not defined", r.name));
            continue;
        };
        if encode(style.foreground) != r.color {
            failures.push(format!(
                "{}: color {} != rich {}",
                r.name,
                encode(style.foreground),
                r.color
            ));
        }
        if encode(style.background) != r.bgcolor {
            failures.push(format!(
                "{}: bgcolor {} != rich {}",
                r.name,
                encode(style.background),
                r.bgcolor
            ));
        }
        for ((attr, want), got) in ATTRS.iter().zip(&r.flags).zip(flags(&style)) {
            // "1" = on; "0" (Rich's `not X`) and "-" (unset) are both off.
            if got != (*want == "1") {
                failures.push(format!("{}: {attr} {got} != rich {want}", r.name));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn style_names_are_rich_names_in_order() {
    let golden: Vec<&str> = records().iter().map(|r| r.name).collect();
    let ours: Vec<&str> = builtin_style_names().collect();
    assert_eq!(ours, golden);
}

#[test]
fn unsupported_attributes_are_only_the_known_ones() {
    // The styles whose Rich definition uses an attribute fast-rich lacks.
    // Only these attributes are skipped by the comparison above.
    let skipped: Vec<(&str, &str)> = records()
        .iter()
        .filter(|r| r.unsupported != "-")
        .map(|r| (r.name, r.unsupported))
        .collect();
    assert_eq!(skipped, [("reset", "blink2"), ("blink2", "blink2")]);
}

#[test]
fn named_colors_match_rich() {
    let mut count = 0;
    for line in COLORS_GOLDEN.lines().filter(|l| !l.starts_with('#')) {
        let (name, index) = line.split_once(' ').unwrap();
        let index: u8 = index.parse().unwrap();
        let color = Color::parse(name).unwrap_or_else(|| panic!("{name} does not parse"));
        assert_eq!(encode(Some(color)), format!("n{index}"), "{name}");
        // Like Rich, 0-15 are the standard colors, the rest 8-bit.
        assert_eq!(matches!(color, Color::Ansi256(_)), index >= 16, "{name}");
        count += 1;
    }
    assert_eq!(count, 235);
}

#[test]
fn named_color_sample() {
    // Spot checks against Rich: Color.parse(name).number.
    for (name, index) in [
        ("grey23", 237),
        ("gray23", 237),
        ("dark_orange3", 166), // listed twice in Rich; the last (166) wins
        ("deep_sky_blue1", 39),
        ("grey100", 231),
        ("navy_blue", 17),
    ] {
        assert_eq!(Color::parse(name), Some(Color::Ansi256(index)), "{name}");
    }
    assert_eq!(
        Style::parse("on grey23").background,
        Some(Color::Ansi256(237))
    );
}

#[test]
fn theme_overrides_default_style() {
    let mut theme = Theme::new();
    theme.add_style("table.header", Style::parse("italic magenta"));
    let s = theme.style("table.header");
    assert!(!s.bold && s.italic);
    assert_eq!(s.foreground, Some(Color::Magenta));
    // Other names keep Rich's defaults.
    assert!(theme.style("table.footer").bold);
}
